import os, subprocess

def submit(*args):
    env = {**os.environ, "SPARK_LOCAL_IP": "127.0.0.1"}
    run = subprocess.run(["spark-submit", *args], capture_output=True, text=True, env=env)
    print("exit code:", run.returncode)
    for line in run.stdout.splitlines():
        if line.startswith("app:"):
            print(line)
    return run

open("/tmp/report.py", "w").write("print('app: started')\n")

def reason(run):
    for line in run.stderr.splitlines():
        if line.startswith("Exception in thread"):
            return line.split("SparkException: ")[1]

run = submit("--master", "local[2]", "--deploy-mode", "cluster", "/tmp/report.py")
print(reason(run))
run = submit("--master", "yarn", "/tmp/report.py")
print(reason(run))
